bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,
 database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),
 max:1,connectionTimeoutMillis:4500});
try{
 const r=await pool.query(`WITH anchor AS (
 SELECT title,seller_user_id FROM videobot_listings WHERE listing_id=$1
 ), classified AS (
 SELECT l.listing_id,l.status,
  (SELECT COUNT(*)::int FROM videobot_stars_ledger t WHERE t.listing_id=l.listing_id AND t.kind='paid') AS native_paid,
  (SELECT COUNT(*)::int FROM videobot_video_invoice_orders o WHERE o.listing_id=l.listing_id) AS invoice_any,
  (SELECT COUNT(*)::int FROM videobot_post_receipts p WHERE p.listing_id=l.listing_id AND p.status='sent' AND p.sale_mode='paid_media') AS native_receipts,
  (SELECT COUNT(*)::int FROM videobot_post_receipts p WHERE p.listing_id=l.listing_id AND p.status<>'sent') AS unresolved_receipts
 FROM videobot_listings l JOIN anchor a ON a.title=l.title AND a.seller_user_id=l.seller_user_id
 WHERE l.status<>'removed')
 SELECT * FROM classified ORDER BY listing_id`,['v26nov24invoice']);
 const a=r.rows;
 if(a.length<2)process.exit(71);
 if(a.length>15)process.exit(72);
 const buyers=a.filter(x=>x.native_paid>0||x.invoice_any>0);
 if(!buyers.length)process.exit(73);
 const unknown=a.filter(x=>x.native_paid===0&&x.invoice_any===0&&(x.native_receipts>0||x.unresolved_receipts>0));
 if(unknown.length)process.exit(74);
 const removable=a.filter(x=>x.native_paid===0&&x.invoice_any===0&&x.native_receipts===0&&x.unresolved_receipts===0);
 if(!removable.length)process.exit(75);
 console.log('VIDEO_DUPLICATE_SAME_TITLE_GROUP=VERIFIED');
 console.log('VIDEO_UNPURCHASED_REMOVABLE_CANDIDATES=VERIFIED');
 console.log('VIDEO_PURCHASED_PRESERVED_CANDIDATES=VERIFIED');
}finally{await pool.end()}
JS
